values
  ('814b7557-bce1-4e70-815b-7d753e140ad0', '09aa3db5-b8ca-41ef-919f-432948d6faff', null, 'topic'::public.curated_course_node_type, 'Economic Reasoning, Scarcity, Choice, and Institutions', 'Microeconomics begins with purposeful choice under constraints. This unit establishes the language of tradeoffs, incentives, marginal analysis, models, and institutions that students will use to interpret every later household, firm, and policy decision.', 0),
  ('edf355eb-db86-497a-a33e-e624b6583000', '09aa3db5-b8ca-41ef-919f-432948d6faff', '814b7557-bce1-4e70-815b-7d753e140ad0', 'subtopic'::public.curated_course_node_type, 'Scarcity and choice', 'Explain why limited time, income, talent, and productive resources force individuals and organizations to choose.', 0),
  ('bd125317-4d58-404b-bac3-8e5d180a517a', '09aa3db5-b8ca-41ef-919f-432948d6faff', 'edf355eb-db86-497a-a33e-e624b6583000', 'concept'::public.curated_course_node_type, 'Wants, resources, constraints, and feasible sets', null, 0),
  ('f5d86e00-7ee3-4ebe-a725-27b2ed525fe8', '09aa3db5-b8ca-41ef-919f-432948d6faff', 'edf355eb-db86-497a-a33e-e624b6583000', 'concept'::public.curated_course_node_type, 'Tradeoffs in personal and organizational decisions', null, 1),
  ('e1c527d9-d8eb-4d10-8963-ec44fe7bd091', '09aa3db5-b8ca-41ef-919f-432948d6faff', 'edf355eb-db86-497a-a33e-e624b6583000', 'concept'::public.curated_course_node_type, 'Positive versus normative questions', null, 2),
  ('57a3e3ae-dab4-4057-8b02-30a1375630ee', '09aa3db5-b8ca-41ef-919f-432948d6faff', 'edf355eb-db86-497a-a33e-e624b6583000', 'concept'::public.curated_course_node_type, 'Efficiency, equity, and other decision criteria', null, 3),
  ('7dda927a-1783-404e-aec1-17e3427c902e', '09aa3db5-b8ca-41ef-919f-432948d6faff', '814b7557-bce1-4e70-815b-7d753e140ad0', 'subtopic'::public.curated_course_node_type, 'Opportunity cost and marginal analysis', 'Evaluate a decision by comparing the best forgone alternative and the incremental benefits and costs of one more unit.', 1),
