  ('c86750eb-e2b7-499a-b15e-08cb988bdae2', '09aa3db5-b8ca-41ef-919f-432948d6faff', 'f581e274-c96c-4538-8522-6ea8c18760f9', 'concept'::public.curated_course_node_type, 'Power, bargaining position, and institutional context', null, 3),
  ('356baa39-dcd1-4c75-834e-59d0072449a9', '09aa3db5-b8ca-41ef-919f-432948d6faff', null, 'topic'::public.curated_course_node_type, 'Specialization, Comparative Advantage, and Economic Evidence', 'Good microeconomic analysis combines a theory of choice with disciplined use of evidence. Students connect production possibilities and comparative advantage to data literacy, experiments, and causal reasoning.', 1),
  ('abde8186-5cc6-428e-83c0-905a9f14ae1f', '09aa3db5-b8ca-41ef-919f-432948d6faff', '356baa39-dcd1-4c75-834e-59d0072449a9', 'subtopic'::public.curated_course_node_type, 'Production possibilities', 'Represent feasible combinations of outputs and use the frontier to explain scarcity, efficiency, and tradeoffs.', 0),
