  ('f52e53ec-d1bd-4045-8e73-81d2c1f27828', '09aa3db5-b8ca-41ef-919f-432948d6faff', '0976cef4-75d9-4e09-926e-0f82dd41b025', 'concept'::public.curated_course_node_type, 'Substitutes, budget share, necessity, and time horizon', null, 2),
