  ('68e272a0-c17e-4b2d-93eb-6770353fef4e', '09aa3db5-b8ca-41ef-919f-432948d6faff', '5182caf4-cfae-48e4-aa72-a0a46dd0ced8', 'subtopic'::public.curated_course_node_type, 'Welfare and distribution', 'Evaluate total gains while making distributional choices and ethical assumptions explicit.', 0),
