insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'textbook'::public.curated_course_resource_kind, 'Principles of Microeconomics 3e', 'https://openstax.org/details/books/principles-microeconomics-3e', 'OpenStax. Free conventional sequence with explanations, graphs, examples, review questions, and exercises.', 0),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'textbook'::public.curated_course_resource_kind, 'The Economy 2.0: Microeconomics', 'https://www.core-econ.org/ebooks/', 'CORE Econ. Evidence-first treatment of institutions, power, firms, strategic interaction, inequality, and environmental limits.', 1),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'textbook'::public.curated_course_resource_kind, 'Microeconomics', 'Pearson', 'Pindyck and Rubinfeld. Applied consumer, producer, market-power, pricing, uncertainty, information, and policy analysis.', 2),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'textbook'::public.curated_course_resource_kind, 'Intermediate Microeconomics: A Modern Approach', 'W. W. Norton', 'Hal R. Varian. Deeper consumer and producer theory, uncertainty, intertemporal choice, welfare, and game theory.', 3),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'textbook'::public.curated_course_resource_kind, 'Managerial Economics and Business Strategy', 'McGraw Hill', 'Baye and Prince. Pricing, demand, production, game theory, information, organization, and managerial decisions.', 4),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'textbook'::public.curated_course_resource_kind, 'The Economics of Strategy', 'Wiley', 'Besanko, Dranove, Shanley, and Schaefer. Competitive advantage, boundaries, commitment, market structure, and organizational economics.', 5),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'textbook'::public.curated_course_resource_kind, 'Thinking Strategically', 'W. W. Norton', 'Dixit and Nalebuff. Readable applications of game theory, commitment, bargaining, entry, and competitive response.', 6),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'website'::public.curated_course_resource_kind, 'MIT 14.01 Principles of Microeconomics', 'https://ocw.mit.edu/courses/14-01-principles-of-microeconomics-fall-2023/', 'Lecture videos, summaries, problem sets, exams, and rigorous conceptual, graphical, and quantitative practice.', 7),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'website'::public.curated_course_resource_kind, 'Wharton BEPP 2500 Managerial Economics', 'https://bepp.wharton.upenn.edu/programs/undergraduate/course-information/course-descriptions/', 'Managerial prescription, business applications, strategic interaction, auctions, and asymmetric information.', 8),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'website'::public.curated_course_resource_kind, 'Yale ECON 159 Game Theory', 'https://oyc.yale.edu/economics/econ-159', 'Complete open course on dominance, Nash equilibrium, sequential games, reputation, bargaining, signaling, and auctions.', 9),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'website'::public.curated_course_resource_kind, 'Marginal Revolution University - Microeconomics', 'https://mru.org/principles-economics-microeconomics', 'Short concept videos, practice, and applied examples for reinforcement or flipped learning.', 10),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'website'::public.curated_course_resource_kind, 'Federal Reserve Economic Data', 'https://fred.stlouisfed.org/', 'Downloadable time series for prices, wages, employment, industries, credit, and market-context assignments.', 11),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'website'::public.curated_course_resource_kind, 'U.S. Bureau of Labor Statistics', 'https://www.bls.gov/data/', 'Official wage, employment, productivity, price, occupational, and industry data.', 12),
  ('09aa3db5-b8ca-41ef-919f-432948d6faff', 'website'::public.curated_course_resource_kind, 'FTC and DOJ Antitrust Resources', 'https://www.ftc.gov/advice-guidance/competition-guidance', 'Primary guidance, cases, merger analysis, competition policy, and remedy examples. Also https://www.justice.gov/atr.', 13);
